/// Fills the workbench colors from the UI theme; unmapped fields keep `c`'s value.
pub(in crate::theme) fn colors(mut c: Colors) -> Colors {
    c.frame = px(0x000000FF); // StatusBar.background
    c.island = px(0x000000FF); // Tree.background
    c.popup = px(0x000000FF); // Popup.background
    c.popup_border = px(0xE6E6E6FF); // Popup.borderColor
    c.field = px(0x000000FF); // TextField.background
    c.notification = px(0x000080FF); // Notification.background
    c.tooltip = px(0x450073FF); // ToolTip.background
    c.text = px(0xFFFFFFFF); // Label.foreground
    c.text_strong = px(0xFFFFFFFF); // Label.foreground
    c.text_secondary = px(0xFFFFFFFF); // StatusBar.Widget.foreground
    c.text_placeholder = px(0xE0861FFF); // Component.infoForeground
    c.text_disabled = px(0xE0861FFF); // Label.disabledForeground
    c.text_on_accent = px(0x000000FF); // Button.default.foreground
    c.hover = px(0x000000FF); // ActionButton.hoverBackground
    c.pressed = px(0x000000FF); // ActionButton.pressedBackground
    c.selection = px(0x3333FFFF); // List.selectionBackground
    c.selection_popup = px(0x3333FFFF); // CompletionPopup.selectionBackground
    c.accent = px(0x1AEBFFFF); // Button.default.startBackground
    c.focus_ring = px(0x1AEBFFFF); // Component.focusColor
    c.border = px(0xE6E6E6FF); // Component.borderColor
    c.separator = px(0xB3B3B3FF); // Separator.separatorColor
    c.group_separator = px(0xB3B3B3FF); // Menu.separatorColor
    c.tab_selected = px(0x000000FF); // EditorTabs.underlinedTabBackground
    c.tab_selected_border = px(0x1AEBFFFF); // EditorTabs.underlineColor
    c.tab_text = px(0xBFBFBFFF); // mix(self:text, self:island, 0.25)
    c.control_border = px(0xFFFFFFFF); // ToggleButton.borderColor
    c.toggle_on = px(0x000080FF); // ToggleButton.onBackground
    c.toggle_off = px(0x000000FF); // ToggleButton.offBackground
    c.toggle_off_knob = px(0xFFFFFFFF); // ToggleButton.buttonColor
    c.border_disabled = px(0xAA6E28FF); // Button.disabledBorderColor
    c.control_selected = px(0x1AEBFFFF); // Button.default.startBackground
    c.selection_inactive = px(0x42424FFF); // List.selectionInactiveBackground
    c.row_hover = px(0x000000FF); // = hover
    c.combo = px(0x000000FF); // ComboBox.ArrowButton.nonEditableBackground
    c.combo_arrow = px(0xFFFFFFFF); // ComboBox.ArrowButton.iconColor
    c.segment_selected = px(0x000000FF); // SegmentedButton.selectedButtonColor
    c.segment_selected_border = px(0x1AEBFFFF); // SegmentedButton.selectedStartBorderColor
    c.progress_track = px(0x404040FF); // ProgressBar.trackColor
    c.counter = px(0xFFFFFFFF); // Counter.background
    c.counter_text = px(0x000000FF); // Counter.foreground
    c.tag = px(0x000000FF); // Tag.background
    c.error = px(0xFA3232FF); // SpeedSearch.errorForeground
    c.warning = px(0xF58231FF); // Component.warningFocusColor
    c.success = px(0x00E61FFF); // ProgressBar.passedColor
    c.link = px(0xD2F53CFF); // Link.activeForeground
    c.banner_info.background = px(0x450073FF); // Banner.infoBackground
    c.banner_info.border = px(0xE6E6E6FF); // Banner.infoBorderColor
    c.banner_warning.background = px(0x804605FF); // Banner.warningBackground
    c.banner_warning.border = px(0xF58231FF); // Banner.warningBorderColor
    c.banner_error.background = px(0x800002FF); // Banner.errorBackground
    c.banner_error.border = px(0xE6194BFF); // Banner.errorBorderColor
    c.banner_success.border = px(0x6FA574FF); // Banner.successBorderColor
    c.run = px(0x5FAD65FF); // RunWidget.runIconColor
    c.stop = px(0xC94F4FFF); // RunWidget.stopBackground
    c.vcs_modified = px(0x4FF0FFFF); // scheme FILESTATUS_MODIFIED
    c.vcs_added = px(0x62CC47FF); // scheme FILESTATUS_ADDED
    c.vcs_untracked = px(0xD1675AFF); // scheme FILESTATUS_UNKNOWN
    c.vcs_ignored = px(0xED864AFF); // scheme FILESTATUS_DELETED
    c.selection_text = px(0xFFFFFFFF); // List.selectionForeground
    c.selection_text_inactive = px(0xBBBBBBFF); // List.selectionInactiveForeground
    c.divider = px(0xB3B3B3FF); // Borders.color
    c.header_active = px(0x450073FF); // ToolWindow.Header.background
    c.header_inactive = px(0x281A33FF); // ToolWindow.Header.inactiveBackground
    c.button_start = px(0x000000FF); // Button.startBackground
    c.button_end = px(0x000000FF); // Button.endBackground
    c.accent_end = px(0x1AEBFFFF); // Button.default.endBackground
    // Kept at the measured value: accent_disabled, text_on_accent_disabled, tab_scroll_thumb, tab_scroll_thumb_hover, control, clear_icon, clear_icon_hover, clear_hover, banner_success.background, icon, folder_fill.
    c
}
